<section class="container section"><div class="page-head"><div><p class="overline">NGHIỆP VỤ / TUYỂN SINH</p><h1>Xét tuyển thí sinh</h1><p class="muted">Kiểm tra điều kiện, cộng điểm ba môn + ưu tiên/khuyến khích, xử lý NV1 → NV2 → NV3 theo chỉ tiêu.</p></div><a class="btn btn-light" href="<?=e(url('quan-tri/diem-chuan?exam_id='.$exam))?>">Sang điểm chuẩn →</a></div>
<form method="get" action="<?=e(url('quan-tri/xet-tuyen'))?>" class="filter-bar"><label>Chọn kỳ tuyển sinh<select name="exam_id" onchange="this.form.submit()"><option value="0">-- Chọn kỳ --</option><?php foreach($exams as $ex):?><option value="<?=$ex['id']?>" <?=$exam==$ex['id']?'selected':''?>><?=e($ex['code'].' – '.$ex['name'])?></option><?php endforeach;?></select></label><button class="btn btn-light">Xem dữ liệu</button></form>
<section class="card spaced"><h2>Danh sách hồ sơ và điều kiện xét tuyển</h2><div class="table-wrap"><table><thead><tr><th>Thí sinh</th><th>Nguyện vọng</th><th>Điều kiện</th><th>Điểm cộng</th><th>Đối chiếu</th></tr></thead><tbody><?php foreach($candidates as $c):?><tr><td><strong><?=e($c['full_name'])?></strong><small class="monospace"><?=e($c['code'])?></small></td><td><?=e($c['choices'])?></td><td><span class="tag <?=$c['eligible']==='eligible'?'green':'gray'?>"><?=e($c['eligible']??'pending')?></span></td><td><?=e(($c['priority_bonus']??0).' + '.($c['encouragement_bonus']??0))?></td><td><details><summary>Kiểm tra điều kiện</summary><form class="mini-form" method="post" action="<?=e(url('quan-tri/dieu-kien'))?>"><?=field('eligibility')?><input type="hidden" name="exam_id" value="<?=$exam?>"><input type="hidden" name="candidate_id" value="<?=$c['id']?>"><label>Kết luận<select name="status"><option value="pending">Chờ kiểm tra</option><option value="eligible" <?=$c['eligible']==='eligible'?'selected':''?>>Đủ điều kiện (demo)</option><option value="ineligible" <?=$c['eligible']==='ineligible'?'selected':''?>>Không đủ điều kiện</option></select></label><label>Ưu tiên<input name="priority_bonus" type="number" step="0.01" min="0" value="<?=e($c['priority_bonus']??0)?>"></label><label>Khuyến khích<input name="encouragement_bonus" type="number" min="0" step="0.01" value="<?=e($c['encouragement_bonus']??0)?>"></label><label>Căn cứ<input name="note" required value="<?=e($c['note']??'Hồ sơ thử nghiệm theo đặc tả')?>"></label><button class="btn btn-main btn-small">Ghi kết luận</button></form></details></td></tr><?php endforeach;?></tbody></table></div></section>
<div class="two-col spaced"><details class="card"><summary>Thêm hồ sơ thử và 3 nguyện vọng</summary><p class="hint">Tự tạo 3 bài thi chưa cấp phách, để bạn thử từ đầu quy trình.</p><form class="stack" method="post" action="<?=e(url('quan-tri/thi-sinh/them'))?>"><?=field('candidate-add')?><input type="hidden" name="exam_id" value="<?=$exam?>"><label>Mã thí sinh<input name="code" required placeholder="IS4-TS07"></label><label>Họ tên<input name="name" required></label><label>Trường THCS<select name="thcs_id"><?php foreach($thcs as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Phòng thi<select name="room_id"><?php foreach($rooms as $r):?><option value="<?=$r['id']?>"><?=e($r['code'])?></option><?php endforeach;?></select></label><?php foreach([1,2,3] as $p):?><label>Nguyện vọng <?=$p?><select name="nv<?=$p?>"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><?php endforeach;?><button class="btn btn-main">Thêm thí sinh</button></form></details>
<section class="card"><h2>Thực hiện xét tuyển</h2><p class="muted">Điểm xét tuyển = Văn + Ngoại ngữ + Toán + điểm cộng. Đồng điểm ở ranh giới chỉ tiêu sẽ được giữ chờ, không tự quyết.</p><form method="post" action="<?=e(url('quan-tri/xet-tuyen/xem-truoc'))?>"><?=field('admission-preview')?><input type="hidden" name="exam_id" value="<?=$exam?>"><button class="btn btn-main">Tính và xem kết quả dự kiến</button></form><p class="hint">Có bước xem trước. Nếu dữ liệu bị thay đổi trước khi xác nhận, hệ thống sẽ chặn lưu và yêu cầu tính lại.</p></section></div>
<?php if($preview):?><section class="card spaced"><h2>Kết quả dự kiến</h2><?php if($preview['data']['issues']):?><div class="alert warning"><strong>Chưa thể xác nhận:</strong><ul><?php foreach($preview['data']['issues'] as $issue):?><li><?=e($issue)?></li><?php endforeach;?></ul></div><?php else:?><div class="alert success">Dữ liệu kiểm tra hợp lệ, có thể lưu kết quả nếu chưa bị thay đổi.</div><?php endif;?><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Thí sinh</th><th>Điểm xét tuyển</th><th>Trường</th><th>NV</th><th>Kết quả</th></tr></thead><tbody><?php foreach($preview['data']['results'] as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['name'])?></td><td><?=fmt($r['score'])?></td><td><?=e($r['school'])?></td><td><?=e($r['priority']??'—')?></td><td><span class="tag <?=$r['school_id']?'green':'gray'?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div><form method="post" action="<?=e(url('quan-tri/xet-tuyen/xac-nhan'))?>" onsubmit="return confirm('Lưu kết quả xét tuyển cho toàn bộ kỳ? Việc này khóa cập nhật nhiều dữ liệu đầu vào.')"><?=field('admission-confirm')?><input type="hidden" name="exam_id" value="<?=$exam?>"><button class="btn btn-main" <?=$preview['data']['issues']?'disabled':''?>>Xác nhận lưu kết quả xét tuyển</button></form></section><?php endif;?>
<?php if($saved):?><section class="card spaced"><h2>Kết quả đã lưu</h2><div class="table-wrap"><table><thead><tr><th>Thí sinh</th><th>Trường</th><th>NV</th><th>Điểm</th><th>Trạng thái</th></tr></thead><tbody><?php foreach($saved as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['school_name']??'—')?></td><td><?=e($r['priority']??'—')?></td><td><?=e($r['score']??'—')?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></section>
